use xiom.io;
fn sum_of_divisors(n: Int) -> Int {
  if n <= 1 { return 0; };
  let mut sum = 1;
  let mut i = 2;
  while i * i <= n {
    if n % i == 0 {
      sum += i;
      let pair = n / i;
      if pair != i { sum += pair; };
    };
    i += 1;
  };
  sum
}

fn is_perfect(n: Int) -> Bool {
  n > 1 && sum_of_divisors(n) == n
}

fn find_perfects(limit: Int) -> Vec[Int] {
  let mut perfects: Vec[Int] = Vec[Int].new();
  let mut n = 2;
  while n <= limit {
    if is_perfect(n) { perfects.push(n); };
    n += 1;
  };
  perfects
}

fn main() -> Int {
  let perfects = find_perfects(10000);
  let mut i = 0;
  while i < perfects.len() {
    io.println(perfects.get(i).unwrap().to_str());
    i += 1;
  };
  return 0;
}
